29	/// Collects all elements of the flow into prepared children. These are much
30	/// simpler to handle than the raw elements.
31	#[typst_macros::time]
32	pub fn collect<'a>(
33	    engine: &mut Engine,
34	    bump: &'a Bump,
35	    children: &[Pair<'a>],
36	    locator: Locator<'a>,
37	    base: Size,
38	    expand: bool,
39	    mode: FlowMode,
40	) -> SourceResult<Vec<Child<'a>>> {
41	    Collector {
42	        engine,
43	        bump,
44	        children,
45	        locator: locator.split(),
46	        base,
47	        expand,
48	        output: Vec::with_capacity(children.len()),
49	        par_situation: ParSituation::First,
50	    }
51	    .run(mode)
52	}
53	
54	/// State for collection.
55	struct Collector<'a, 'x, 'y> {
56	    engine: &'x mut Engine<'y>,
57	    bump: &'a Bump,
58	    children: &'x [Pair<'a>],
59	    base: Size,
60	    expand: bool,
61	    locator: SplitLocator<'a>,
62	    output: Vec<Child<'a>>,
63	    par_situation: ParSituation,
64	}
65	
66	impl<'a> Collector<'a, '_, '_> {
67	    /// Perform the collection.
68	    fn run(self, mode: FlowMode) -> SourceResult<Vec<Child<'a>>> {
69	        match mode {
70	            FlowMode::Root | FlowMode::Block => self.run_block(),
71	            FlowMode::Inline => self.run_inline(),
72	        }
73	    }
74	
75	    /// Perform collection for block-level children.
76	    fn run_block(mut self) -> SourceResult<Vec<Child<'a>>> {
77	        for &(child, styles) in self.children {
78	            if let Some(elem) = child.to_packed::<TagElem>() {
79	                self.output.push(Child::Tag(&elem.tag));
80	            } else if let Some(elem) = child.to_packed::<VElem>() {
81	                self.v(elem, styles);
82	            } else if let Some(elem) = child.to_packed::<ParElem>() {
83	                self.par(elem, styles)?;
84	            } else if let Some(elem) = child.to_packed::<BlockElem>() {
85	                self.block(elem, styles);
86	            } else if let Some(elem) = child.to_packed::<PlaceElem>() {
87	                self.place(elem, styles)?;
88	            } else if child.is::<FlushElem>() {
89	                self.output.push(Child::Flush);
90	            } else if let Some(elem) = child.to_packed::<ColbreakElem>() {
91	                self.output.push(Child::Break(elem.weak.get(styles)));
92	                self.par_situation = ParSituation::First;
93	            } else if child.is::<PagebreakElem>() {
94	                bail!(
95	                    child.span(), "pagebreaks are not allowed inside of containers";
96	                    hint: "try using a `#colbreak()` instead";
97	                );
98	            } else {
99	                self.engine.sink.warn(warning!(
100	                    child.span(),
101	                    "{} was ignored during paged export",
102	                    child.func().name(),
103	                ));
104	            }
105	        }
106	
107	        Ok(self.output)
108	    }
109	
110	    /// Perform collection for inline-level children.
111	    fn run_inline(mut self) -> SourceResult<Vec<Child<'a>>> {
112	        // Extract leading and trailing tags.
113	        let (start, end) = self.children.split_prefix_suffix(|(c, _)| c.is::<TagElem>());
114	        let inner = &self.children[start..end];
115	
116	        // Compute the shared styles.
117	        let styles = StyleChain::trunk_from_pairs(inner).unwrap_or_default();
118	
119	        // Layout the lines.
120	        let lines = crate::inline::layout_inline(
121	            self.engine,
122	            inner,
123	            &mut self.locator,
124	            styles,
125	            self.base,
126	            self.expand,
127	        )?
128	        .into_frames();
129	
130	        for (c, _) in &self.children[..start] {
131	            let elem = c.to_packed::<TagElem>().unwrap();
132	            self.output.push(Child::Tag(&elem.tag));
133	        }
134	
135	        let leading = styles.resolve(ParElem::leading);
136	        self.lines(lines, leading, styles);
137	
138	        for (c, _) in &self.children[end..] {
139	            let elem = c.to_packed::<TagElem>().unwrap();
140	            self.output.push(Child::Tag(&elem.tag));
141	        }
142	
143	        Ok(self.output)
144	    }
145	
146	    /// Collect vertical spacing into a relative or fractional child.
147	    fn v(&mut self, elem: &'a Packed<VElem>, styles: StyleChain<'a>) {
148	        self.output.push(match elem.amount {
149	            Spacing::Rel(rel) => {
150	                Child::Rel(rel.resolve(styles), elem.weak.get(styles) as u8)
151	            }
152	            Spacing::Fr(fr) => Child::Fr(fr, elem.weak.get(styles) as u8),
153	        });
154	    }
155	
156	    /// Collect a paragraph into [`LineChild`]ren. This already performs line
157	    /// layout since it is not dependent on the concrete regions.
158	    fn par(
159	        &mut self,
160	        elem: &'a Packed<ParElem>,
161	        styles: StyleChain<'a>,
162	    ) -> SourceResult<()> {
163	        let lines = crate::inline::layout_par(
164	            elem,
165	            self.engine,
166	            self.locator.next(&elem.span()),
167	            styles,
168	            self.base,
169	            self.expand,
170	            self.par_situation,
171	        )?
172	        .into_frames();
173	
174	        let spacing = elem.spacing.resolve(styles);
175	        let leading = elem.leading.resolve(styles);
176	
177	        self.output.push(Child::Rel(spacing.into(), 4));
178	
179	        self.lines(lines, leading, styles);
180	
181	        self.output.push(Child::Rel(spacing.into(), 4));
182	        self.par_situation = ParSituation::Consecutive;
183	
184	        Ok(())
185	    }
186	
187	    /// Collect laid-out lines.
188	    fn lines(&mut self, lines: Vec<Frame>, leading: Abs, styles: StyleChain<'a>) {
189	        let align = styles.resolve(AlignElem::alignment);
190	        let costs = styles.get(TextElem::costs);
191	
192	        // Determine whether to prevent widow and orphans.
193	        let len = lines.len();
194	        let prevent_orphans =
195	            costs.orphan() > Ratio::zero() && len >= 2 && !lines[1].is_empty();
196	        let prevent_widows =
197	            costs.widow() > Ratio::zero() && len >= 2 && !lines[len - 2].is_empty();
198	        let prevent_all = len == 3 && prevent_orphans && prevent_widows;
199	
200	        // Store the heights of lines at the edges because we'll potentially
201	        // need these later when `lines` is already moved.
202	        let height_at = |i| lines.get(i).map(Frame::height).unwrap_or_default();
203	        let front_1 = height_at(0);
204	        let front_2 = height_at(1);
205	        let back_2 = height_at(len.saturating_sub(2));
206	        let back_1 = height_at(len.saturating_sub(1));
207	
208	        for (i, frame) in lines.into_iter().enumerate() {
209	            if i > 0 {
210	                self.output.push(Child::Rel(leading.into(), 5));
211	            }
212	
213	            // To prevent widows and orphans, we require enough space for
214	            // - all lines if it's just three
215	            // - the first two lines if we're at the first line
216	            // - the last two lines if we're at the second to last line
217	            let need = if prevent_all && i == 0 {
218	                front_1 + leading + front_2 + leading + back_1
219	            } else if prevent_orphans && i == 0 {
220	                front_1 + leading + front_2
221	            } else if prevent_widows && i >= 2 && i + 2 == len {
222	                back_2 + leading + back_1
223	            } else {
224	                frame.height()
225	            };
226	
227	            self.output
228	                .push(Child::Line(self.boxed(LineChild { frame, align, need })));
229	        }
230	    }
