343	/// A prepared child in flow layout.
344	///
345	/// The larger variants are bump-boxed to keep the enum size down.
346	#[derive(Debug)]
347	pub enum Child<'a> {
348	    /// An introspection tag.
349	    Tag(&'a Tag),
350	    /// Relative spacing with a specific weakness level.
351	    Rel(Rel<Abs>, u8),
352	    /// Fractional spacing with a specific weakness level.
353	    Fr(Fr, u8),
354	    /// An already layouted line of a paragraph.
355	    Line(BumpBox<'a, LineChild>),
356	    /// An unbreakable block.
357	    Single(BumpBox<'a, SingleChild<'a>>),
358	    /// A breakable block.
359	    Multi(BumpBox<'a, MultiChild<'a>>),
360	    /// An absolutely or floatingly placed element.
361	    Placed(BumpBox<'a, PlacedChild<'a>>),
362	    /// A place flush.
363	    Flush,
364	    /// An explicit column break.
365	    Break(bool),
366	}
