389	impl SingleChild<'_> {
390	    /// Build the child's frame given the region's base size.
391	    pub fn layout(&self, engine: &mut Engine, region: Region) -> SourceResult<Frame> {
392	        self.cell.get_or_init(region, |mut region| {
393	            // Vertical expansion is only kept if this block is the only child.
394	            region.expand.y &= self.alone;
395	            layout_single_impl(
396	                engine.world,
397	                engine.library,
398	                engine.introspector.into_raw(),
399	                engine.traced,
400	                TrackedMut::reborrow_mut(&mut engine.sink),
401	                engine.route.track(),
402	                self.elem,
403	                self.locator.track(),
404	                self.styles,
405	                region,
406	            )
407	        })
408	    }
409	}
