411	/// The cached, internal implementation of [`SingleChild::layout`].
412	#[comemo::memoize]
413	#[expect(clippy::too_many_arguments)]
414	fn layout_single_impl(
415	    world: Tracked<dyn World + '_>,
416	    library: &LazyHash<Library>,
417	    introspector: Tracked<dyn Introspector + '_>,
418	    traced: Tracked<Traced>,
419	    sink: TrackedMut<Sink>,
420	    route: Tracked<Route>,
421	    elem: &Packed<BlockElem>,
422	    locator: Tracked<Locator>,
423	    styles: StyleChain,
424	    region: Region,
425	) -> SourceResult<Frame> {
426	    let introspector = Protected::from_raw(introspector);
427	    let link = LocatorLink::new(locator);
428	    let locator = Locator::link(&link);
429	    let mut engine = Engine {
430	        library,
431	        world,
432	        introspector,
433	        traced,
434	        sink,
435	        route: Route::extend(route),
436	    };
437	
438	    layout_and_modify(styles, |styles| {
439	        layout_single_block(elem, &mut engine, locator, styles, region)
440	    })
441	}
