443	/// A child that encapsulates a prepared breakable block.
444	#[derive(Debug)]
445	pub struct MultiChild<'a> {
446	    pub align: Axes<FixedAlignment>,
447	    pub sticky: bool,
448	    alone: bool,
449	    elem: &'a Packed<BlockElem>,
450	    styles: StyleChain<'a>,
451	    locator: Locator<'a>,
452	    cell: CachedCell<SourceResult<Fragment>>,
453	}
454	
455	impl<'a> MultiChild<'a> {
456	    /// Build the child's frames given regions.
457	    pub fn layout<'b>(
458	        &'b self,
459	        engine: &mut Engine,
460	        regions: Regions,
461	    ) -> SourceResult<(Frame, Option<MultiSpill<'a, 'b>>)> {
462	        let fragment = self.layout_full(engine, regions)?;
463	        let exist_non_empty_frame = fragment.iter().any(|f| !f.is_empty());
464	
465	        // Extract the first frame.
466	        let mut frames = fragment.into_iter();
467	        let frame = frames.next().unwrap();
468	
469	        // If there's more, return a `spill`.
470	        let mut spill = None;
471	        if frames.next().is_some() {
472	            spill = Some(MultiSpill {
473	                exist_non_empty_frame,
474	                multi: self,
475	                full: regions.full,
476	                first: regions.size.y,
477	                backlog: vec![],
478	                min_backlog_len: regions.backlog.len(),
479	            });
480	        }
481	
482	        Ok((frame, spill))
483	    }
484	
485	    /// The shared internal implementation of [`Self::layout`] and
486	    /// [`MultiSpill::layout`].
487	    fn layout_full(
488	        &self,
489	        engine: &mut Engine,
490	        regions: Regions,
491	    ) -> SourceResult<Fragment> {
492	        self.cell.get_or_init(regions, |mut regions| {
493	            // Vertical expansion is only kept if this block is the only child.
494	            regions.expand.y &= self.alone;
495	            layout_multi_impl(
496	                engine.world,
497	                engine.library,
498	                engine.introspector.into_raw(),
499	                engine.traced,
500	                TrackedMut::reborrow_mut(&mut engine.sink),
501	                engine.route.track(),
502	                self.elem,
503	                self.locator.track(),
504	                self.styles,
505	                regions,
506	            )
507	        })
508	    }
509	}
