514	fn layout_multi_impl(
515	    world: Tracked<dyn World + '_>,
516	    library: &LazyHash<Library>,
517	    introspector: Tracked<dyn Introspector + '_>,
518	    traced: Tracked<Traced>,
519	    sink: TrackedMut<Sink>,
520	    route: Tracked<Route>,
