543	/// The spilled remains of a `MultiChild` that broke across two regions.
544	#[derive(Debug, Clone)]
545	pub struct MultiSpill<'a, 'b> {
546	    pub(super) exist_non_empty_frame: bool,
547	    multi: &'b MultiChild<'a>,
548	    first: Abs,
549	    full: Abs,
550	    backlog: Vec<Abs>,
551	    min_backlog_len: usize,
552	}
553	
554	impl MultiSpill<'_, '_> {
555	    /// Build the spill's frames given regions.
556	    pub fn layout(
557	        mut self,
558	        engine: &mut Engine,
559	        regions: Regions,
560	    ) -> SourceResult<(Frame, Option<Self>)> {
561	        // The first region becomes unchangeable and committed to our backlog.
562	        self.backlog.push(regions.size.y);
563	
564	        // The remaining regions are ephemeral and may be replaced.
565	        let mut backlog: Vec<_> =
566	            self.backlog.iter().chain(regions.backlog).copied().collect();
567	
568	        // Remove unnecessary backlog items to prevent it from growing
569	        // unnecessarily, changing the region's hash.
570	        while backlog.len() > self.min_backlog_len
571	            && backlog.last().copied() == regions.last
572	        {
573	            backlog.pop();
574	        }
575	
576	        // Build the pod with the merged regions.
577	        let pod = Regions {
578	            size: Size::new(regions.size.x, self.first),
579	            expand: regions.expand,
580	            full: self.full,
581	            backlog: &backlog,
582	            last: regions.last,
583	        };
584	
585	        // Extract the not-yet-processed frames.
586	        let mut frames = self
587	            .multi
588	            .layout_full(engine, pod)?
589	            .into_iter()
590	            .skip(self.backlog.len());
591	
592	        // Ensure that the backlog never shrinks, so that unwrapping below is at
593	        // least fairly safe. Note that the whole region juggling here is
594	        // fundamentally not ideal: It is a compatibility layer between the old
595	        // (all regions provided upfront) & new (each region provided on-demand,
596	        // like an iterator) layout model. This approach is not 100% correct, as
597	        // in the old model later regions could have an effect on earlier
598	        // frames, but it's the best we can do for now, until the multi
599	        // layouters are refactored to the new model.
600	        self.min_backlog_len = self.min_backlog_len.max(backlog.len());
601	
602	        // Save the first frame.
603	        let frame = frames.next().unwrap();
604	
605	        // If there's more, return a `spill`.
606	        let mut spill = None;
607	        if frames.next().is_some() {
608	            spill = Some(self);
609	        }
610	
611	        Ok((frame, spill))
612	    }
613	
614	    /// The alignment of the breakable block.
615	    pub fn align(&self) -> Axes<FixedAlignment> {
616	        self.multi.align
617	    }
618	}
